    prepare(s,n);accept(s,n);expected=s.timeZone.auditExpected(J.obj("offset",0,"timezoneStrategy","system"));check("Custom audit prerequisite is exact current native setting only",expected.optBoolean("timezoneNativeReadback")&&expected.optString("timezoneRequestedZone").equals("Asia/Tokyo")&&!expected.optBoolean("pageObservationVerified"));
